import numpy as np
def load(fn):
    lines=open(fn).read().splitlines()
    n=int(lines[0]); ats=[l.split() for l in lines[2:2+n]]
    C=np.array([[float(a[1]),float(a[2]),float(a[3])] for a in ats]); return C
def d(C,i,j): return float(np.linalg.norm(C[i]-C[j]))
def dih(C,i,j,k,l):
    p0,p1,p2,p3=C[i],C[j],C[k],C[l]
    b0=-(p1-p0); b1=p2-p1; b2=p3-p2
    b1/=np.linalg.norm(b1)
    v=b0-np.dot(b0,b1)*b1; w=b2-np.dot(b2,b1)*b1
    x=np.dot(v,w); y=np.dot(np.cross(b1,v),w)
    return float(np.degrees(np.arctan2(y,x)))
for fn in ['initial_my.xyz','opt_ff_my.xyz','opt_ff2.xyz','xtbopt.xyz']:
    C=load(fn)
    print(fn,'N-C17 %.2f  dih(P,N,Co1,Co2) %.1f  ang(Co1,N,P) %.1f  Co1-P %.2f Co2-P %.2f'%(d(C,4,17),dih(C,84,4,0,1),0 if fn=='x' else 0,d(C,0,84),d(C,1,84)))
def ang(C,i,j,k):
    v1=C[i]-C[j]; v2=C[k]-C[j]
    return float(np.degrees(np.arccos(np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2))))
for fn in ['initial_my.xyz','opt_ff_my.xyz','opt_ff2.xyz','xtbopt.xyz']:
    C=load(fn)
    print(fn,'ang Co1-N_l-P %.1f  ang Co1-N_l-C17 %.1f  ang C17-N_l-P %.1f'%(ang(C,0,4,84),ang(C,0,4,17),ang(C,17,4,84)))
